256	    // DELETE /api/config/credentials/:id — remove a single entry by id
257	    // Sync handler (no request body to parse — unlike the async PUT above).
258	    // ------------------------------------------------------------------
259	    router.delete('/api/config/credentials/:id', (
260	        _req: IncomingMessage,
261	        res: ServerResponse,
262	        params: Record<string, string>,
263	    ): void => {
264	        let credId: string;
265	        try {
266	            credId = decodeURIComponent(params['id']);
267	        } catch {
268	            sendError(res, 400, 'Malformed id parameter.');
269	            return;
270	        }
271	
272	        const existing = appConfig.gitCredentials ?? [];
273	        const idx = existing.findIndex((e) => e.id === credId);
274	
275	        if (idx === -1) {
276	            sendError(res, 404, `No credential entry found with id "${credId}".`);
277	            return;
278	        }
279	
280	        const updated = existing.filter((_, i) => i !== idx);
281	
282	        // When the array is empty, remove the field entirely.
283	        appConfig.gitCredentials = updated.length > 0 ? updated : undefined;
284	
285	        saveConfigField('gitCredentials', appConfig.gitCredentials, configPath);
286	
287	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
288	    });
